class Solution {
  public long popcountDepth(long n, int k) {
    if (k == 0) return 1;
    int[] depth = new int[64];
    for (int x = 2; x < 64; x++) depth[x] = depth[Integer.bitCount(x)] + 1;
    long[][] c = new long[64][64];
    for (int i = 0; i < 64; i++) {
      c[i][0] = 1;
      for (int j = 1; j <= i; j++) c[i][j] = c[i - 1][j - 1] + (j <= i - 1 ? c[i - 1][j] : 0);
    }
    long total = 0;
    for (int p = 1; p < 64; p++) {
      if (depth[p] != k - 1) continue;
      // count of x in [1, n] with exactly p set bits
      long count = 0;
      int ones = 0;
      for (int b = 62; b >= 0; b--) {
        if ((n >> b & 1) == 0) continue;
        if (p - ones >= 0 && b >= p - ones) count += c[b][p - ones];
        ones++;
      }
      if (ones == p) count++;
      total += count;
    }
    if (k == 1) total--;
    return total;
  }
}
